function damageBenchmark(s,target,move,evs){const atkStats=actualStats(s),base=master(target.name)?.slice(3,9).map(Number);if(!atkStats||!base)return null;const defStats=calculateStats(base,evs,null),type=koreanType[move[2]]||move[2],category=move[3],attack=category==='물리'?atkStats[1]:atkStats[3],defense=category==='물리'?defStats[2]:defStats[4],stab=row(s.name).types.includes(type)?(s.abilities==='적응력'?2:1.5):1,typeMult=multiplier(type,target.types),mod=stab*typeMult*itemPower(s.items,type,category)*abilityPower(s.abilities,type,category);return classifyKO(damageRolls(Number(move[4]),attack,defense,mod),defStats[0])}
function damageTable(s,targets){const moves=s.moves.map(n=>D.master.moves.find(x=>x[0]===n)).filter(m=>m&&m[3]!=='변화'&&Number(m[4])>0),baseScenarios=[[0,0,0,0,0,0],[32,0,0,0,0,0]];if(!moves.length)return '';const rows=targets.map(t=>{const p=row(t.name);if(!p)return '';const candidates=moves.map(m=>({m,base:damageBenchmark(s,p,m,baseScenarios[0])})).filter(x=>x.base).sort((a,b)=>b.base.maxPct-a.base.maxPct),best=candidates[0];if(!best)return '';const full=best.m[3]==='물리'?[32,0,32,0,0,0]:[32,0,0,0,32,0],results=[...baseScenarios,full].map(v=>damageBenchmark(s,p,best.m,v)),cell=r=>`<td><b>${esc(r.label)}</b><small>${r.minPct}~${r.maxPct}%</small></td>`;return `<tr><td><button class="monlink" data-detail="${esc(p.name)}">${esc(p.name)}</button><small>${esc(best.m[0])} · 위력 ${best.m[4]} · 명중 ${best.m[5]}</small></td>${results.map(cell).join('')}</tr>`}).join('');return `<details class="damagebench"><summary>상위 메타 타수 기준 보기</summary><div class="tablewrap"><table><thead><tr><th>상대 / 최고 피해 기술</th><th>H0·내구0</th><th>H32·내구0</th><th>H32·B/D32</th></tr></thead><tbody>${rows}</tbody></table></div><p>상대 무보정 성격, 86~100의 15개 데미지 난수 기준입니다. 마지막 열은 물리기면 H32 B32, 특수기면 H32 D32입니다. 명중률·급소·날씨·필드·랭크·벽·상대 특성/도구·연속기 횟수·가변 위력·더블 광역 보정은 제외합니다.</p></details>`}
function performanceHtml(ts){const targets=(O?.modes[mode]?.frequency||stats().slice(0,20).map(p=>({name:p.name,rate:0}))).slice(0,20);return `<div class="analysisitem performance"><h3>투자 결과와 결정력</h3><p>챔피언스 스탯 포인트를 반영한 실능력치입니다. 결정력 지수는 공격/특공 × 기술 기본 위력 × 자속 × 확인 가능한 도구·상시 특성 보정입니다.</p>${ts.map(s=>{const a=actualStats(s),zero=actualStats(s,[0,0,0,0,0,0]),speed=Math.floor(a[5]*(s.items==='구애스카프'?1.5:1)),bench=targets.map(t=>{const b=master(t.name);return b?{name:t.name,s0:Number(b[8])+20,s32:Number(b[8])+52}:null}).filter(Boolean),beat0=bench.filter(x=>speed>x.s0),beat32=bench.filter(x=>speed>x.s32),close=bench.sort((x,y)=>Math.abs(x.s32-speed)-Math.abs(y.s32-speed)).slice(0,4),moves=s.moves.map(n=>D.master.moves.find(x=>x[0]===n)).filter(m=>m&&m[3]!=='변화'&&Number(m[4])>0).map(m=>{const type=koreanType[m[2]]||m[2],atk=m[3]==='물리'?a[1]:a[3],stab=row(s.name).types.includes(type)?(s.abilities==='적응력'?2:1.5):1,index=Math.round(atk*Number(m[4])*stab*itemPower(s.items,type,m[3])*abilityPower(s.abilities,type,m[3]));return {name:m[0],index}}).sort((x,y)=>y.index-x.index),physical=Math.round(a[0]*a[2]),special=Math.round(a[0]*a[4]),pGain=Math.round((physical/(zero[0]*zero[2])-1)*100),sGain=Math.round((special/(zero[0]*zero[4])-1)*100);return `<section class="performancecard"><strong>${esc(s.name)} · 실능력치 ${a.join(' / ')}</strong><p>현재 스피드 ${speed}${s.items==='구애스카프'?' (구애스카프 반영)':''} · 상위 ${bench.length}종 중 무보정 S0 ${beat0.length}종, S32 ${beat32.length}종보다 빠름<br><small>가까운 S32 기준: ${close.map(x=>esc(x.name)+' '+x.s32).join(' · ')||'비교 자료 없음'}</small></p><p>물리 내구 지수 ${physical.toLocaleString()} (${pGain>=0?'+':''}${pGain}%) · 특수 내구 지수 ${special.toLocaleString()} (${sGain>=0?'+':''}${sGain}%)<br><small>괄호는 같은 성격의 무투자 상태 대비 HP×방어/특방 변화입니다.</small></p><p>결정력 지수: ${moves.map(x=>esc(x.name)+' '+x.index.toLocaleString()).join(' · ')||'위력이 있는 선택 기술 없음'}</p>${damageTable(s,targets.slice(0,10))}</section>`}).join('')}</div>`}
