const TYPE_COLORS={노말:[168,167,122],불꽃:[238,129,48],물:[99,144,240],전기:[247,208,44],풀:[122,199,76],얼음:[150,217,214],격투:[194,46,40],독:[163,62,161],땅:[226,191,101],비행:[169,143,243],에스퍼:[249,85,135],벌레:[166,185,26],바위:[182,161,54],고스트:[115,87,151],드래곤:[111,53,252],악:[112,87,70],강철:[183,183,206],페어리:[214,133,173]};
function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image;img.onload=()=>resolve(img);img.onerror=reject;img.src=src})}
function plainCrop(img,x,y,w,h,size=72){x=Math.max(0,x);y=Math.max(0,y);w=Math.max(1,Math.min(w,img.width-x));h=Math.max(1,Math.min(h,img.height-y));const c=document.createElement('canvas'),ratio=w/h;c.width=size;c.height=Math.max(36,Math.round(size/ratio));c.getContext('2d').drawImage(img,x,y,w,h,0,0,c.width,c.height);return c}
const learnedKey='champions-recognition-v1';
function learnedReferences(){try{return JSON.parse(localStorage.getItem(learnedKey)||'[]').filter(x=>x&&row(x.name)&&validVisualFeature(x.feature))}catch{return[]}}
function saveLearnedReferences(entries){const old=learnedReferences(),next=[...old];for(const entry of entries){const same=next.map((x,i)=>({x,i})).filter(({x})=>x.name===entry.name&&x.side===entry.side);while(same.length>=4){next.splice(same.shift().i,1);for(const s of same)s.i--}next.push({...entry,feature:compactFeature(entry.feature),source:'사용자 확인'})}try{localStorage.setItem(learnedKey,JSON.stringify(next.slice(-120)))}catch{return false}spriteFeaturePromise=null;return true}
