async function spriteFeatures(){if(spriteFeaturePromise)return spriteFeaturePromise;const listed=new Set(stats().map(p=>p.name)),official=(RECOGNITION_DB.references||[]).filter(r=>listed.has(r.name)&&r.src&&r.source!=='현재 목록 기본 이미지'&&r.source!=='PokeAPI 보조').map(r=>imageReference({...r,source:r.source||'챔피언스 UI'}));spriteFeaturePromise=Promise.all(official).then(x=>[...learnedReferences(),...x.filter(Boolean)]);return spriteFeaturePromise}
function detectPreviewTypes(img,layout,i){const pw=layout.x1-layout.x0,spacing=i?layout.rows[i]-layout.rows[i-1]:layout.rows[1]-layout.rows[0],c=plainCrop(img,layout.x0+pw*.68,layout.rows[i]-spacing*.39,pw*.31,spacing*.78,80),d=c.getContext('2d').getImageData(0,0,c.width,c.height).data,count={},corners=[[0,0],[c.width-1,0],[0,c.height-1],[c.width-1,c.height-1]].map(([x,y])=>{const j=(y*c.width+x)*4;return[d[j],d[j+1],d[j+2]]}),bg=corners.reduce((a,v)=>a.map((x,k)=>x+v[k]/4),[0,0,0]);for(let j=0;j<d.length;j+=4){if(Math.hypot(d[j]-bg[0],d[j+1]-bg[1],d[j+2]-bg[2])<48)continue;const[h,s,v]=rgbHsv(d[j],d[j+1],d[j+2]);if(s<.28||v<.25)continue;let best='',distance=Infinity;for(const[name,rgb]of Object.entries(TYPE_COLORS)){const x=Math.hypot(d[j]-rgb[0],d[j+1]-rgb[1],d[j+2]-rgb[2]);if(x<distance){best=name;distance=x}}if(distance<92)count[best]=(count[best]||0)+1}const ranked=Object.entries(count).sort((a,b)=>b[1]-a[1]),top=ranked[0]?.[1]||0;if(top<18)return[];return ranked.filter(x=>x[1]>=Math.max(18,top*.38)).slice(0,2).map(x=>x[0])}
function leadStats(name){const p=row(name);if(!p)return '';const list=(k,n)=>p[k].slice(0,n).map(x=>`${esc(x.name)} ${x.rate}%`).join(' · ')||'통계 없음';return `<div class="leadstat"><b>${esc(p.types.join(' / '))}</b><small>기술 ${list('moves',4)}<br>특성 ${list('abilities',2)}<br>도구 ${list('items',2)}</small></div>`}
