async function setLeadFile(f){if(!f)return;if(!imageOk(f))return toast('15MB 이하 PNG, JPG, WebP를 선택해 주세요.');leadFile=f;if(leadURL)URL.revokeObjectURL(leadURL);leadURL=URL.createObjectURL(f);$('leadPreview').src=leadURL;$('leadPreview').hidden=false;$('leadPreview').title='클릭해서 크게 보기';$('leadRead').disabled=false;$('leadStatus').textContent='이미지 준비됨 · 자동 인식을 시작합니다.';if(!$('leadRemove'))$('leadPreview').insertAdjacentHTML('afterend','<button id="leadRemove" class="imageremove">이미지 삭제</button>');await recognizeLead()}
