async function recognizeLead(){
 if(!leadFile)return;
 $('leadRead').disabled=true;$('leadRecommend').disabled=true;
 try{
  $('leadStatus').textContent='OpenAI가 선출 화면을 읽는 중… 최대 55초 소요됩니다.';
  const result=await recognizeImages({files:[leadFile],mode,kind:'lead'});
  for(const side of ['mine','opp'])lead[side]=result.sides[side].map(slot=>{const name=row(slot.name)?slot.name:'';return {name,candidates:name?[name]:[],crop:'',confidence:slot.confidence,notes:slot.notes}});
  renderLead();const named=[...lead.mine,...lead.opp].filter(x=>x.name).length;$('leadStatus').textContent=`AI 인식 완료 · ${named}/12마리 확인 · 후보 또는 검색으로 모두 확인한 뒤 선출을 추천하세요.`;
 }catch(e){$('leadStatus').textContent=e.message||'선출 화면 인식에 실패했습니다.'}finally{$('leadRead').disabled=false}
}
