$('lead').addEventListener('click',e=>{if(e.target.id==='leadRemove'){if(leadURL)URL.revokeObjectURL(leadURL);leadURL='';leadFile=null;$('leadPreview').hidden=true;e.target.remove();$('leadRead').disabled=true;$('leadStatus').textContent='이미지를 선택하거나 끌어다 놓으세요.';return}const b=e.target.closest('[data-leadname]');if(!b)return;lead[b.dataset.leadside][+b.dataset.leadindex].name=b.dataset.leadname;renderLead()});
$('lead').addEventListener('input',e=>{if(e.target.dataset.leadsearch===undefined)return;const side=e.target.dataset.leadsearch,i=+e.target.dataset.leadindex,q=norm(e.target.value),target=document.querySelector(`[data-leadmatches="${side}-${i}"]`),list=q?stats().filter(p=>norm(p.name).includes(q)).slice(0,12):[];target.innerHTML=list.map(p=>`<button class="pickrow" data-leadside="${side}" data-leadindex="${i}" data-leadname="${esc(p.name)}"><span>${esc(p.name)}</span><small>${p.rank}위 · ${esc(p.types.join(' / '))}</small></button>`).join('')||(q?'<small>검색 결과가 없습니다.</small>':'')});
function leadSet(name){return team().find(x=>x?.name===name)||makeSet(row(name))}
function maxDamage(source,target,set=leadSet(source.name)){const moves=set.moves.map(n=>D.master.moves.find(x=>x[0]===n)).filter(m=>m&&m[3]!=='변화'&&Number(m[4])>0);return moves.map(m=>({move:m[0],...damageBenchmark(set,target,m,[0,0,0,0,0,0])})).filter(x=>Number.isFinite(x.maxPct)).sort((a,b)=>b.maxPct-a.maxPct)[0]||{move:'유효타 없음',minPct:0,maxPct:0,label:'효과 없음'}}
