function combination(items,n,start=0,pick=[],out=[]){if(pick.length===n){out.push([...pick]);return out}for(let i=start;i<=items.length-(n-pick.length);i++){pick.push(items[i]);combination(items,n,i+1,pick,out);pick.pop()}return out}
function subsetScore(group,opponents){const results=group.map(n=>leadMatch(n,opponents)),coverage=opponents.reduce((a,o)=>a+Math.max(...results.map(r=>r.duels.find(x=>x.name===o).score)),0),synergy=group.reduce((a,n,i)=>a+group.slice(i+1).filter(m=>row(n).teammates.includes(m)||row(m).teammates.includes(n)).length*6,0),gaps=teamTypeSummary(stats(),group).filter(x=>x.weak.length&&!x.resist.length).length;return {group,results,score:coverage+results.reduce((a,r)=>a+r.score,0)*.18+synergy-gaps*2}}
$('leadRecommend').onclick=()=>{const mine=lead.mine.map(x=>x.name),opponents=lead.opp.map(x=>x.name),count=mode==='single'?3:4;if(new Set(mine).size<6||new Set(opponents).size<6)return toast('양쪽 여섯 마리를 중복 없이 확인해 주세요.');const best=combination(mine,count).map(g=>subsetScore(g,opponents)).sort((a,b)=>b.score-a.score)[0];let order;if(mode==='double'){const pairs=combination(best.group,2).map(pair=>({pair,score:subsetScore(pair,opponents).score+(row(pair[0]).teammates.includes(pair[1])||row(pair[1]).teammates.includes(pair[0])?10:0)})).sort((a,b)=>b.score-a.score)[0].pair;order=[...pairs,...best.group.filter(n=>!pairs.includes(n)).sort((a,b)=>leadMatch(b,opponents).score-leadMatch(a,opponents).score)]}else order=[...best.group].sort((a,b)=>leadMatch(b,opponents).score-leadMatch(a,opponents).score);const labels=mode==='single'?['선봉','2번','3번']:['선봉 1','선봉 2','후발 1','후발 2'];$('leadResult').innerHTML=`<section class="leadrecommend"><h3>${mode==='single'?'싱글 3마리':'더블 4마리'} 추천</h3><div class="leadorder">${order.map((n,i)=>`<article><span>${labels[i]}</span>${monSprite(n,'large')}<button class="monlink" data-detail="${esc(n)}">${esc(n)}</button></article>`).join('')}</div>${order.map(n=>{const r=leadMatch(n,opponents),good=[...r.duels].sort((a,b)=>b.score-a.score).slice(0,2),bad=[...r.duels].sort((a,b)=>a.score-b.score)[0];return `<p><b>${esc(n)}</b> — 유리 후보 ${good.map(x=>`${esc(x.name)} (${esc(x.out.move)} ${x.out.minPct}~${x.out.maxPct}%, ${x.out.label})`).join(' · ')}<br><small>주의: ${esc(bad.name)}의 통계 상위 세팅 기준 최대 피해 ${bad.incoming.minPct}~${bad.incoming.maxPct}% · ${bad.incoming.label}</small></p>`}).join('')}<p class="leadnotice">선택한 내 세팅, 상대의 통계 최상위 세팅, 타입 상성·자속·기술 위력·공격/방어 실능력치·확인 가능한 도구/상시 특성 보정, 쓰러뜨린 상대와 팀메이트 통계를 함께 계산했습니다. 상대 실제 세팅과 교체·변화기 운영은 알 수 있으므로 최종 선택 전 후보를 확인하세요.</p></section>`;$('leadResult').scrollIntoView({behavior:'smooth',block:'nearest'})};
function renderRanked(){if(!O){$('rankedSummary').textContent='오픈데이터를 불러오지 못했습니다.';return}const d=O.modes[mode],q=$('rankedSearch').value.trim();$('rankedSummary').textContent=`${d.season} · 공개 파티 ${d.count}개 · 원문 갱신 ${d.updatedAt} (JST)`;$('openFrequency').innerHTML=d.frequency.slice(0,8).map((f,i)=>`<div class="freq"><span class="type">표본 내 ${i+1}위</span>${monSprite(f.name,'large')}<button class="monlink" data-detail="${esc(f.name)}">${esc(f.name)}</button><b>${f.rate}%</b><small>${f.count} / ${d.count}개 파티</small></div>`).join('');$('rankedTeams').innerHTML=d.teams.filter(t=>!q||t.team.some(m=>m.name.includes(q))).map(t=>`<article class="rankedteam"><div class="sectionhead"><h2>최종 ${t.rank}위 <span>레이팅 ${t.rating.toFixed(3)}</span></h2><button data-ranked="${t.rank}">파티로 가져오기</button></div><div class="rankedsix">${t.team.map(m=>`<div>${monSprite(m.name,'medium')}<button class="monlink" data-detail="${esc(m.name)}">${esc(m.name)}</button><small>${esc(m.item||'도구 없음')}</small></div>`).join('')}</div></article>`).join('')}
$('rankedSearch').oninput=renderRanked;
document.addEventListener('click',e=>{const b=e.target.closest('[data-ranked]');if(!b||!O)return;const t=O.modes[mode].teams.find(t=>t.rank===+b.dataset.ranked);if(team().some(Boolean)&&!confirm('현재 파티를 이 상위 파티로 교체할까요?'))return;let missing=[];let next=t.team.map(m=>{const p=row(m.name);if(!p){missing.push(m.name);return null}const s=makeSet(p);if(p.items.some(v=>v.name===m.item))s.items=m.item;else{s.items='';missing.push(m.name+' 도구')}return s});teams[mode]=next;persist();render();document.querySelector('[data-tab="builder"]').click();toast(missing.length?'가져왔습니다. 첨부 상세 통계에 없는 항목은 비워 두었습니다: '+missing.join(', '):'구성과 도구를 가져왔습니다. 나머지 세팅은 첨부 통계 기반 초안입니다.')});
const calculator=setupCalculator({$,stats,row,team,makeSet,data:D,toast,damageBenchmark,actualStats,master,itemPower,abilityPower,esc,evtext,koreanType,multiplier,strongestStatMove,damageScenarioResults,speedVariants});
render();renderOcr();calculator.renderNames();

$('ocrResults').addEventListener('input',e=>{const i=e.target.dataset.ocrquery;if(i===undefined)return;const q=norm(e.target.value),target=document.querySelector(`[data-ocrmatches="${i}"]`);const list=q?stats().filter(p=>norm(p.name).includes(q)):[];target.innerHTML=q?(list.slice(0,12).map(p=>`<button class="pickrow" data-ocrcandidate="${i}" data-name="${esc(p.name)}"><span>${esc(p.name)}</span><small>${p.rank}위 · ${esc(p.types.join(' / '))}</small></button>`).join('')||'<p>검색 결과가 없습니다.</p>'):''});
$('ocrResults').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.ocrcandidate!==undefined){setOcrName(+b.dataset.ocrcandidate,b.dataset.name);renderOcr();toast(b.dataset.name+' 선택됨 · 도구와 기술을 확인해 주세요.')}if(b.dataset.ocrclear!==undefined){setOcrName(+b.dataset.ocrclear,'');renderOcr()}});
document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}));
function showDetails(name){const p=row(name),base=master(name);$('detailTitle').textContent=name+' · 상세 통계';if(!base){$('detailBody').innerHTML='<p>첨부 데이터에 해당 정보가 없습니다.</p>';$('details').showModal();return}const src=O?.modes[mode],freq=src?.frequency.find(x=>x.name===name);let head=`<div class="detailhero">${monSprite(name,'detail')}<div><strong>${esc(name)}</strong><p>${esc(base[2])} · 상세 통계 ${D.date} · ${mode==='single'?'싱글':'더블'} ${p?p.rank+'위':'통계 없음'}</p></div></div><div class="basestats">${['HP','공격','방어','특공','특방','스피드'].map((l,i)=>`<div><small>${l}</small><strong>${base[i+3]}</strong></div>`).join('')}</div><p>${freq?'공개 상위 파티 표본: '+freq.rate+'% ('+freq.count+'/'+src.count+'개 파티)':'공개 상위 파티 표본에 등재되지 않음'} · 전체 랭크배틀 사용률 아님</p>`;if(p){const table=(key,label)=>`<section class="statsection"><h3>${label}</h3><table><thead><tr><th>선택</th><th>항목</th><th>채용률</th></tr></thead><tbody>${p[key].map((v,i)=>{const m=D.master[key]?.find(x=>x[0]===v.name);let extra=key==='evs'?'합계 '+sum(evparse(v.name))+' ✓':key==='moves'&&m?(koreanType[m[2]]||m[2])+' / '+m[3]+' / 위력 '+m[4]+' / 명중 '+m[5]:key==='items'||key==='abilities'?m?.[2]||'':key==='natures'&&m?'상승 '+m[2]+' / 하락 '+m[3]:'';const control=key==='moves'?`<input type="checkbox" name="detail-moves" value="${esc(v.name)}" ${i<4?'checked':''} aria-label="${esc(v.name)} 선택">`:`<input type="radio" name="detail-${key}" value="${esc(v.name)}" ${i===0?'checked':''} aria-label="${esc(v.name)} 선택">`;return `<tr><td>${control}</td><td>${esc(v.name)}<small>${esc(extra)}</small></td><td>${v.rate}%</td></tr>`}).join('')||'<tr><td colspan="3">확인된 항목 없음</td></tr>'}</tbody></table></section>`;head+=`<div class="detailactions"><button class="primary" data-detailbuild="${esc(name)}">선택한 통계 구성 적용</button><button data-detailcustom="${esc(name)}">전체 목록에서 직접 설정</button></div><p class="detailnotice">기술은 최대 4개를 선택하세요. 각 채용률은 독립 집계이므로 이 조합 전체의 동시 채용률은 아닙니다.</p><div class="detailstats">${[['moves','기술'],['items','도구'],['abilities','특성'],['natures','성격'],['evs','능력 배분']].map(([k,l])=>table(k,l)).join('')}</div><section class="statsection"><h3>팀메이트</h3><div class="candidates">${p.teammates.map(n=>`<button data-detail="${esc(n)}">${esc(n)}</button>`).join('')||'첨부 데이터 없음'}</div></section><section class="statsection"><h3>이 포켓몬을 쓰러뜨린 상대</h3><p>원본의 쓰러뜨린 포켓몬 통계이며, 팀메이트 추천과 파티 점검의 실전 대응 근거로 사용합니다.</p>${p.counters.map(c=>`<p><button class="monlink" data-detail="${esc(c.name)}">${esc(c.name)}</button> · 승률 ${c.rate}% · 표본 ${c.n}</p>`).join('')||'<p>원본에 해당 통계 없음</p>'}</section>`}head+='<p>상세 통계 미등재 항목은 직접 설정에서 챔피언스 전체 마스터 목록으로 선택할 수 있습니다. 기술·특성의 포켓몬별 사용 가능 여부는 현재 자료에 없으므로 직접 확인해야 합니다.</p>';$('detailBody').innerHTML=head;if(!$('details').open)$('details').showModal();$('details').scrollTop=0}
$('detailBody').addEventListener('change',e=>{if(e.target.name!=='detail-moves'||!e.target.checked)return;const selected=$('detailBody').querySelectorAll('input[name="detail-moves"]:checked');if(selected.length>4){e.target.checked=false;toast('기술은 최대 4개까지 선택할 수 있습니다.')}});
$('detailBody').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.detailcustom){const name=b.dataset.detailcustom,target=team().findIndex(x=>x?.name===name);$('details').close();edit(target,name)}if(b.dataset.detailbuild){const name=b.dataset.detailbuild,p=row(name),pick=k=>$('detailBody').querySelector(`input[name="detail-${k}"]:checked`)?.value||'',moves=[...$('detailBody').querySelectorAll('input[name="detail-moves"]:checked')].map(x=>x.value),evs=evparse(pick('evs')),s={name,items:pick('items'),abilities:pick('abilities'),natures:pick('natures'),moves,evs};if(!validSet(s))return toast('도구·특성·성격·배분과 기술 1~4개를 선택해 주세요.');let target=team().findIndex(x=>x?.name===name);if(target<0)target=team().indexOf(null);if(target<0)return toast('파티가 가득 찼습니다. 먼저 한 자리를 비워 주세요.');team()[target]=s;persist();render();$('details').close();toast(`${name}의 선택한 통계 구성을 파티에 적용했습니다.`)}});
$('sourceBtn').addEventListener('click',()=>{$('sourceBody').insertAdjacentHTML('beforeend','<p><b>이미지 인식 참조:</b> 현재 모드 리스팅 235종만 후보로 사용합니다. 사용자 제공 챔피언스 화면의 확정 아이콘과 기기에서 사용자가 확정한 화면 특징을 우선 비교하고, PokeAPI의 폼별 일반색·이로치 렌더는 보조 후보로만 사용합니다. 타입색 추정은 후보 점수에 강제 반영하지 않습니다. pokedb 상세 페이지의 이미지는 해당 사이트 이용약관상 일괄 수집하지 않습니다. 이미지 자료는 포켓몬·기술·도구·특성·메타 데이터에 사용하지 않습니다.</p>')});
